import { randomUUID } from 'node:crypto';
import type { DatabaseSync } from 'node:sqlite';

/** Processing constants shared by the worker. */
export const STEP_MS = 100;
export const MAX_ATTEMPTS = 3;
export const RETRY_DELAY_MS = 500;
/** The worker counts as up if its heartbeat is at most this old. */
export const HEARTBEAT_FRESH_MS = 3_000;

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** A row of the `jobs` table, as SQLite returns it. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  completed_steps: number;
  result_output: string | null;
  error: string | null;
  idempotency_key: string | null;
  fingerprint: string | null;
  next_run_at: number;
  created_at: string;
  updated_at: string;
}

/** The public job representation returned by the API. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

export interface FieldError {
  field: string;
  message: string;
}

export function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed_steps, total: row.steps },
    result: row.status === 'completed' && row.result_output !== null ? { output: row.result_output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

const SUBMISSION_FIELDS = new Set(['input', 'steps', 'failAttempts']);

const isPlainObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);

function integerField(body: Record<string, unknown>, name: 'steps' | 'failAttempts', min: number, max: number, fallback: number, fields: FieldError[]): number {
  const value = body[name];
  if (value === undefined) return fallback;
  if (typeof value !== 'number' || !Number.isInteger(value) || value < min || value > max) {
    fields.push({ field: name, message: `Must be an integer from ${min} to ${max}.` });
    return fallback;
  }
  return value;
}

/** Validates a parsed submission body. Returns the job to create, or every offending field. */
export function validateSubmission(body: unknown): { ok: true; value: NewJob } | { ok: false; fields: FieldError[] } {
  if (!isPlainObject(body)) return { ok: false, fields: [{ field: 'body', message: 'Body must be a JSON object.' }] };
  const fields: FieldError[] = [];
  for (const key of Object.keys(body)) {
    if (!SUBMISSION_FIELDS.has(key)) fields.push({ field: key, message: 'Unknown field.' });
  }
  let input = '';
  const raw = body.input;
  if (typeof raw !== 'string') {
    fields.push({ field: 'input', message: 'Required string.' });
  } else if (raw.length < 1 || raw.length > 1000) {
    fields.push({ field: 'input', message: 'Must be 1 to 1000 characters.' });
  } else if (raw.trim() === '') {
    fields.push({ field: 'input', message: 'Must not be only whitespace.' });
  } else {
    input = raw;
  }
  const steps = integerField(body, 'steps', 1, 20, 5, fields);
  const failAttempts = integerField(body, 'failAttempts', 0, 5, 0, fields);
  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, value: { input, steps, failAttempts } };
}

export type SubmitResult = { kind: 'created' | 'replayed'; job: Job } | { kind: 'conflict' };

/** Creates a job, or replays/rejects according to the idempotency key. Atomic via BEGIN IMMEDIATE. */
export function submitJob(db: DatabaseSync, value: NewJob, key: string | undefined): SubmitResult {
  const fingerprint = JSON.stringify([value.input, value.steps, value.failAttempts]);
  const now = new Date().toISOString();
  db.exec('BEGIN IMMEDIATE');
  try {
    if (key !== undefined) {
      const existing = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(key) as JobRow | undefined;
      if (existing) {
        db.exec('COMMIT');
        return existing.fingerprint === fingerprint ? { kind: 'replayed', job: toJob(existing) } : { kind: 'conflict' };
      }
    }
    const id = randomUUID();
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed_steps, idempotency_key, fingerprint, next_run_at, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?)`,
    ).run(id, value.input, value.steps, value.failAttempts, key ?? null, key === undefined ? null : fingerprint, now, now);
    const row = db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow;
    db.exec('COMMIT');
    return { kind: 'created', job: toJob(row) };
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}

export function getJob(db: DatabaseSync, id: string): Job | undefined {
  const row = db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as JobRow | undefined;
  return row ? toJob(row) : undefined;
}

export function listJobs(db: DatabaseSync): Job[] {
  return (db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[]).map(toJob);
}

// ---- Worker-side operations -------------------------------------------------------------------

/** Claims the oldest queued job that is due, marking it running and counting the attempt. */
export function claimNextJob(db: DatabaseSync, nowMs: number): JobRow | undefined {
  db.exec('BEGIN IMMEDIATE');
  try {
    const next = db
      .prepare("SELECT id FROM jobs WHERE status = 'queued' AND next_run_at <= ? ORDER BY seq LIMIT 1")
      .get(nowMs) as { id: string } | undefined;
    if (!next) {
      db.exec('COMMIT');
      return undefined;
    }
    db.prepare(
      "UPDATE jobs SET status = 'running', attempts = attempts + 1, completed_steps = 0, updated_at = ? WHERE id = ?",
    ).run(new Date(nowMs).toISOString(), next.id);
    const row = db.prepare('SELECT * FROM jobs WHERE id = ?').get(next.id) as unknown as JobRow;
    db.exec('COMMIT');
    return row;
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}

export function setProgress(db: DatabaseSync, id: string, completed: number): void {
  db.prepare('UPDATE jobs SET completed_steps = ?, updated_at = ? WHERE id = ?').run(completed, new Date().toISOString(), id);
}

export function completeJob(db: DatabaseSync, id: string, output: string): void {
  db.prepare(
    "UPDATE jobs SET status = 'completed', result_output = ?, error = NULL, completed_steps = steps, updated_at = ? WHERE id = ?",
  ).run(output, new Date().toISOString(), id);
}

export function failJob(db: DatabaseSync, id: string, error: string): void {
  db.prepare("UPDATE jobs SET status = 'failed', error = ?, result_output = NULL, updated_at = ? WHERE id = ?").run(
    error,
    new Date().toISOString(),
    id,
  );
}

export function scheduleRetry(db: DatabaseSync, id: string, runAtMs: number): void {
  db.prepare("UPDATE jobs SET status = 'queued', completed_steps = 0, next_run_at = ?, updated_at = ? WHERE id = ?").run(
    runAtMs,
    new Date().toISOString(),
    id,
  );
}

/**
 * Returns jobs left `running` by a stopped worker to the queue. The interrupted attempt is not
 * counted, so the re-run is the same attempt number and the retry limits still hold.
 */
export function requeueInterrupted(db: DatabaseSync): number {
  const result = db
    .prepare("UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), completed_steps = 0, next_run_at = 0, updated_at = ? WHERE status = 'running'")
    .run(new Date().toISOString());
  return Number(result.changes);
}

// ---- Heartbeat --------------------------------------------------------------------------------

export function writeHeartbeat(db: DatabaseSync, nowMs: number): void {
  db.prepare('INSERT INTO heartbeats (name, at) VALUES (?, ?) ON CONFLICT(name) DO UPDATE SET at = excluded.at').run('worker', nowMs);
}

export function clearHeartbeat(db: DatabaseSync): void {
  db.prepare("DELETE FROM heartbeats WHERE name = 'worker'").run();
}

export function isWorkerUp(db: DatabaseSync, nowMs: number): boolean {
  const row = db.prepare("SELECT at FROM heartbeats WHERE name = 'worker'").get() as { at: number } | undefined;
  return row !== undefined && nowMs - row.at <= HEARTBEAT_FRESH_MS;
}

