import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import { getJob, isWorkerUp, listJobs, submitJob, validateSubmission, type FieldError } from './jobs.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

/** Largest request body accepted; anything bigger is rejected as an invalid body. */
const MAX_BODY_BYTES = 1_000_000;
const IDEMPOTENCY_KEY = /^[A-Za-z0-9_-]{1,128}$/;
const JOB_PATH = /^\/api\/jobs\/([^/]+)$/;

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  send(res, status, { error: fields ? { code, message, fields } : { code, message } });
}

/** Responds 405 and returns false unless the request method is allowed on this path. */
function methodAllowed(req: IncomingMessage, res: ServerResponse, methods: string[]): boolean {
  if (methods.includes(req.method ?? '')) return true;
  res.setHeader('allow', methods.join(', '));
  sendError(res, 405, 'method_not_allowed', `${req.method} is not allowed on this path.`);
  return false;
}

function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

async function createJobRoute(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const raw = await readBody(req);
  const fields: FieldError[] = [];
  let parsed: unknown;
  let haveBody = false;

  const mediaType = (req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json.' });
  } else if (raw.tooLarge) {
    fields.push({ field: 'body', message: `Body must be at most ${MAX_BODY_BYTES} bytes.` });
  } else {
    try {
      parsed = JSON.parse(raw.text);
      haveBody = true;
    } catch {
      fields.push({ field: 'body', message: 'Body must be valid JSON.' });
    }
  }

  let key: string | undefined;
  const keyHeader = req.headers['idempotency-key'];
  if (keyHeader !== undefined) {
    if (typeof keyHeader === 'string' && IDEMPOTENCY_KEY.test(keyHeader)) key = keyHeader;
    else fields.push({ field: 'Idempotency-Key', message: 'Must match ^[A-Za-z0-9_-]{1,128}$.' });
  }

  if (haveBody) {
    const v = validateSubmission(parsed);
    if (v.ok) {
      if (fields.length === 0) {
        const result = submitJob(db, v.value, key);
        if (result.kind === 'conflict') {
          return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
        }
        return send(res, result.kind === 'created' ? 201 : 200, result.job);
      }
    } else {
      fields.push(...v.fields);
    }
  }
  sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');

  if (pathname === '/health') {
    if (!methodAllowed(req, res, ['GET'])) return;
    return send(res, 200, { status: 'ok', worker: isWorkerUp(db, Date.now()) ? 'up' : 'down' });
  }
  if (pathname === '/') {
    if (!methodAllowed(req, res, ['GET'])) return;
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (!methodAllowed(req, res, ['GET', 'POST'])) return;
    if (req.method === 'POST') return createJobRoute(req, res);
    return send(res, 200, { jobs: listJobs(db) });
  }
  const match = JOB_PATH.exec(pathname);
  if (match) {
    if (!methodAllowed(req, res, ['GET'])) return;
    const job = getJob(db, match[1]!);
    if (!job) return sendError(res, 404, 'not_found', 'No job with that id.');
    return send(res, 200, job);
  }
  sendError(res, 404, 'not_found', 'No such route.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
  });
});

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  server.close();
  server.closeAllConnections();
  db.close();
  process.exit(0);
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

server.listen(port, () => console.log(`server listening on ${port}`));

