import { setInterval as every, setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import {
  claimNextJob,
  clearHeartbeat,
  completeJob,
  failJob,
  MAX_ATTEMPTS,
  requeueInterrupted,
  RETRY_DELAY_MS,
  scheduleRetry,
  setProgress,
  STEP_MS,
  type JobRow,
  writeHeartbeat,
} from './jobs.ts';

const db = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

/** Processes one claimed attempt. Returns early without changing the job if the worker is stopping. */
async function runAttempt(job: JobRow): Promise<void> {
  // Attempt n fails at its first step, before any progress, while n <= failAttempts.
  if (job.attempts <= job.fail_attempts) {
    await sleep(STEP_MS);
    if (stopping) return;
    if (job.attempts >= MAX_ATTEMPTS) failJob(db, job.id, 'transient failure');
    else scheduleRetry(db, job.id, Date.now() + RETRY_DELAY_MS);
    return;
  }
  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return;
    setProgress(db, job.id, step);
  }
  completeJob(db, job.id, job.input.toUpperCase());
}

// A job still `running` here was interrupted by an earlier worker that died; process it again.
const recovered = requeueInterrupted(db);
if (recovered > 0) console.log(`requeued ${recovered} interrupted job(s)`);

writeHeartbeat(db, Date.now());
const heartbeat = (async () => {
  for await (const _ of every(1_000)) {
    if (stopping) break;
    writeHeartbeat(db, Date.now());
  }
})();

console.log('worker started');
while (!stopping) {
  const job = claimNextJob(db, Date.now());
  if (!job) {
    await sleep(200);
    continue;
  }
  await runAttempt(job);
}

// Stopping: any attempt still in progress goes back to the queue, then the worker goes down.
requeueInterrupted(db);
await heartbeat;
clearHeartbeat(db);
db.close();
console.log('worker stopped');

